var RESCOM_API=''; /* optionnel : URL d’un Google Apps Script (voir participation_rescom.gs) pour compter les participants de tous les téléphones */
function rcReg(){try{return JSON.parse(localStorage.getItem('camp_registration_2026')||'null')||{}}catch(e){return {}}}
function rcGet(){try{return JSON.parse(localStorage.getItem('campRescomJoin')||'null')}catch(e){return null}}
function rcCount(){if(!RESCOM_API)return;fetch(RESCOM_API+'?action=count').then(function(r){return r.json()}).then(function(d){if(d&&typeof d.count==='number'){window._rcN=d.count;rescomPaint()}}).catch(function(){})}
window.rescomPaint=function(){var j=rcGet(),r=rcReg();
 document.querySelectorAll('[data-rescom-join]').forEach(function(b){b.classList.toggle('on',!!j);b.querySelector('span').textContent=j?'Je participe ✓':'Participer'});
 document.querySelectorAll('[data-rescom-count]').forEach(function(e){var n=window._rcN;e.innerHTML=(typeof n==='number')?('<b>'+n+'</b> '+(n>1?'personnes souhaitent':'personne souhaite')+' participer'):(j?'Ta participation est enregistrée. Merci !':'Appuie sur Participer pour réserver ta place.')});
 var t=encodeURIComponent('Bonjour, je souhaite participer à l’Atelier RESCOM du Camp de District.\nNom : '+(r.Name||'')+'\nTroupe : '+(r.Group||'')+'\nTéléphone : '+(r.Phone||''));
 document.querySelectorAll('[data-rescom-wa]').forEach(function(a){a.hidden=!j;a.href='https://wa.me/2250506172317?text='+t})};
document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-rescom-join]');if(!b)return;
 var j=rcGet(),r=rcReg();
 if(j){if(!confirm('Annuler ta participation à l’atelier ?'))return;try{localStorage.removeItem('campRescomJoin')}catch(x){}j=null}
 else{j={n:r.Name||'',p:r.Phone||'',g:r.Group||'',d:Date.now()};try{localStorage.setItem('campRescomJoin',JSON.stringify(j))}catch(x){}b.classList.remove('pop');void b.offsetWidth;b.classList.add('pop');if(navigator.vibrate)try{navigator.vibrate(20)}catch(x){}}
 if(RESCOM_API){var q=RESCOM_API+'?action='+(j?'join':'leave')+'&name='+encodeURIComponent((j?j.n:r.Name)||'')+'&phone='+encodeURIComponent((j?j.p:r.Phone)||'')+'&group='+encodeURIComponent((j?j.g:r.Group)||'');fetch(q,{mode:'no-cors'}).then(function(){setTimeout(rcCount,800)}).catch(function(){})}
 rescomPaint()});
