function saveNb(){try{localStorage.setItem('campFilComments',JSON.stringify(nb))}catch(e){}}
function burst(btn){
 var svg=btn.querySelector('svg');if(!svg)return;
 var r=svg.getBoundingClientRect(),b=btn.getBoundingClientRect();
 var cx=r.left-b.left+r.width/2,cy=r.top-b.top+r.height/2,cols=['#e0245c','#ff7410','#ffb300','#ff5c8a'];
 var ring=document.createElement('i');ring.className='lk-ring';ring.style.left=cx+'px';ring.style.top=cy+'px';btn.appendChild(ring);
 for(var i=0;i<8;i++){
  var d=document.createElement('i'),a=(Math.PI*2*i/8)+Math.random()*.4,k=22+Math.random()*10;
  d.className='lk-dot';d.style.left=cx+'px';d.style.top=cy+'px';d.style.background=cols[i%4];
  d.style.setProperty('--dx',Math.cos(a)*k+'px');d.style.setProperty('--dy',Math.sin(a)*k+'px');
  btn.appendChild(d)}
 setTimeout(function(){btn.querySelectorAll('.lk-dot,.lk-ring').forEach(function(e){e.remove()})},750)}
var USR='<svg viewBox="0 0 24 24"><circle cx="12" cy="8.5" r="3.6"/><path d="M5 20c1-4 4-5.5 7-5.5s6 1.5 7 5.5"/></svg>',RX=['👍','❤️','😂','😮','😢','🙏'];
function me(){var n='Vous',p='';try{var a=localStorage.getItem('camp_avatar'),r=JSON.parse(localStorage.getItem('camp_registration_2026')||'null');if(r&&r.Name)n=r.Name;p=a||(r&&r.Photo&&String(r.Photo).indexOf('data:')===0?r.Photo:'')}catch(e){}return{n:n,p:p}}
function setAv(el){if(!el)return;var m=me();el.classList.toggle('ph',!!m.p);el.style.backgroundImage=m.p?'url('+m.p+')':'';el.innerHTML=m.p?'':USR}
